func bcryptHash(password string) (string, error) {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), 4)
	return string(hash), err
}

// The integration suite exercises the flows that carry the product's security
// promises — single-use QR, approval gating, consent capture, throttling — end
// to end against a real PostgreSQL. Set VISITFLOW_TEST_DSN to a server the test
// may create and drop databases on; without it the suite skips.
const testAdminPassword = "integration-test-password"

type testEnv struct {
	server  *Server
	handler http.Handler
	cookies []*http.Cookie
	csrf    string
	t       *testing.T
}

func randomSuffix(t *testing.T) string {
	t.Helper()
	b := make([]byte, 8)
	if _, err := rand.Read(b); err != nil {
		t.Fatalf("random: %v", err)
	}
	return fmt.Sprintf("%x", b)
}

func newTestEnv(t *testing.T) *testEnv {
	t.Helper()
	adminDSN := strings.TrimSpace(os.Getenv("VISITFLOW_TEST_DSN"))
	if adminDSN == "" {
		t.Skip("VISITFLOW_TEST_DSN is not set; skipping PostgreSQL integration test")
	}
	ctx := context.Background()
	adminPool, err := pgxpool.New(ctx, adminDSN)
	if err != nil {
		t.Fatalf("connect admin database: %v", err)
	}
	if err := adminPool.Ping(ctx); err != nil {
		adminPool.Close()
		t.Fatalf("ping admin database: %v", err)
	}
	name := "visitflow_test_" + randomSuffix(t)
	if _, err := adminPool.Exec(ctx, `CREATE DATABASE `+name); err != nil {
		adminPool.Close()
		t.Fatalf("create test database: %v", err)
	}
	parsed, err := url.Parse(adminDSN)
	if err != nil {
		t.Fatalf("parse dsn: %v", err)
	}
	parsed.Path = "/" + name
	pool, err := database.Open(ctx, parsed.String())
	if err != nil {
		t.Fatalf("open test database: %v", err)
	}
	t.Cleanup(func() {
		pool.Close()
		if _, err := adminPool.Exec(context.Background(), `DROP DATABASE IF EXISTS `+name+` WITH (FORCE)`); err != nil {
			t.Logf("drop test database: %v", err)
		}
		adminPool.Close()
	})
	server := newServerForPool(t, pool)
	env := &testEnv{server: server, handler: server.Routes(), t: t}
	env.login("admin", testAdminPassword)
	return env
}

func newServerForPool(t *testing.T, pool *pgxpool.Pool) *Server {
	t.Helper()
	key := make([]byte, 32)
	if _, err := rand.Read(key); err != nil {
		t.Fatalf("random key: %v", err)
	}
	keyring, err := platform.NewKeyringFromSecret(base64.StdEncoding.EncodeToString(key))
	if err != nil {
		t.Fatalf("keyring: %v", err)
	}
	server := NewServer(pool, keyring, slog.New(slog.NewTextHandler(io.Discard, nil)),
		fstest.MapFS{"index.html": {Data: []byte("<html><head></head><body>spa</body></html>")}}, "test", "test", "test")
	ctx := context.Background()
	if err := server.EnsureEncryptionKey(ctx); err != nil {
		t.Fatalf("encryption key: %v", err)
	}
	if err := server.EnsureBootstrapAdmin(ctx, "admin", testAdminPassword); err != nil {
		t.Fatalf("bootstrap admin: %v", err)
	}
	return server
}

// testRequestTimeout bounds a single request made through do or doForwarded.
// No request in this suite takes more than a few seconds, so a request that is
// still running at this point is stuck. Failing that one test — with the path
// that stalled — beats letting the whole package run into go test's timeout,
// where the only diagnosis is a stack dump of every goroutine.
const testRequestTimeout = 30 * time.Second

// requestContext derives a request context from the test's own, so a request
// is cancelled either when it stalls or when its test has already ended.
func (e *testEnv) requestContext() (context.Context, context.CancelFunc) {
	return context.WithTimeout(e.t.Context(), testRequestTimeout)
}

// requestTimedOut reports why a request should fail its test, or "" if its
// context simply ran to completion.
func requestTimedOut(ctx context.Context, method, path string) string {
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return fmt.Sprintf("%s %s did not finish within %s; the handler is stuck", method, path, testRequestTimeout)
	}
	return ""
}

func (e *testEnv) do(method, path string, body any) *httptest.ResponseRecorder {
	e.t.Helper()
	ctx, cancel := e.requestContext()
	defer cancel()
	response := e.doWithContext(ctx, method, path, body)
	if reason := requestTimedOut(ctx, method, path); reason != "" {
		e.t.Fatal(reason)
	}
	return response
}

// doWithContext is do with a caller-supplied request context. httptest never
// cancels a request on its own, so a handler that only returns when the client
// goes away — the lobby SSE stream — needs a context with a deadline or it
// blocks the whole package until go test's timeout kills it.
func (e *testEnv) doWithContext(ctx context.Context, method, path string, body any) *httptest.ResponseRecorder {
	e.t.Helper()
	var reader io.Reader
	if body != nil {
		encoded, err := json.Marshal(body)
		if err != nil {
			e.t.Fatalf("encode body: %v", err)
		}
		reader = strings.NewReader(string(encoded))
	}
	request := httptest.NewRequest(method, path, reader).WithContext(ctx)
	request.RemoteAddr = "10.0.0.1:5000"
	if body != nil {
		request.Header.Set("Content-Type", "application/json")
	}
	if e.csrf != "" {
		request.Header.Set("X-CSRF-Token", e.csrf)
	}
	for _, cookie := range e.cookies {
		request.AddCookie(cookie)
	}
	response := httptest.NewRecorder()
	e.handler.ServeHTTP(response, request)
	for _, cookie := range response.Result().Cookies() {
		e.cookies = append(e.cookies, cookie)
	}
	return response
}

// doForwarded sends a request that claims a different origin address, which is
// what an attacker does to spread throttled attempts over many counters.
func (e *testEnv) doForwarded(method, path, forwardedFor string) *httptest.ResponseRecorder {
	e.t.Helper()
	ctx, cancel := e.requestContext()
	defer cancel()
	request := httptest.NewRequest(method, path, nil).WithContext(ctx)
	request.RemoteAddr = "10.0.0.1:5000"
	request.Header.Set("X-Forwarded-For", forwardedFor)
	request.Header.Set("X-Real-IP", forwardedFor)
	response := httptest.NewRecorder()
	e.handler.ServeHTTP(response, request)
	if reason := requestTimedOut(ctx, method, path); reason != "" {
		e.t.Fatal(reason)
	}
	return response
}

func (e *testEnv) json(method, path string, body any, wantStatus int) map[string]any {
	e.t.Helper()
	response := e.do(method, path, body)
	if response.Code != wantStatus {
		e.t.Fatalf("%s %s returned %d (want %d): %s", method, path, response.Code, wantStatus, response.Body.String())
	}
	if response.Body.Len() == 0 {
		return map[string]any{}
	}
	var decoded map[string]any
	if err := json.Unmarshal(response.Body.Bytes(), &decoded); err != nil {
		return map[string]any{}
	}
	return decoded
}

name: CI

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

jobs:
  test:
    runs-on: ubuntu-24.04
    services:
      postgres:
        image: postgres:16-alpine
        env:
          POSTGRES_USER: visitflow
          POSTGRES_PASSWORD: visitflow
          POSTGRES_DB: visitflow
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U visitflow"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 10
    steps:
      - uses: actions/checkout@v6
      - uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@v6
        with:
          node-version: 24
          cache: npm
          cache-dependency-path: web/package-lock.json
      - name: Go tests and vet
        env:
          # The integration suite creates and drops a database per test, so it
          # needs an account that may run CREATE DATABASE.
          VISITFLOW_TEST_DSN: postgres://visitflow:visitflow@127.0.0.1:5432/visitflow?sslmode=disable
        run: |
          go test ./... -count=1
          go vet ./...
      - name: React production build
        working-directory: web
        run: |
          npm ci
          npm test
          npm run build
      - name: Docker image build
        run: docker build --build-arg VERSION=ci --build-arg COMMIT="$GITHUB_SHA" --build-arg BUILT_AT=ci -t visitflow:ci .

  e2e:
    runs-on: ubuntu-24.04
    services:
      postgres:
        image: postgres:16-alpine
        env:
          POSTGRES_USER: visitflow
          POSTGRES_PASSWORD: visitflow
          POSTGRES_DB: visitflow
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U visitflow"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 10
    env:
      VISITFLOW_E2E_ADMIN: admin
      VISITFLOW_E2E_PASSWORD: e2e-bootstrap-password
    steps:
      - uses: actions/checkout@v6
      - uses: actions/setup-go@v7
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@v6
        with:
          node-version: 24
          cache: npm
          cache-dependency-path: web/package-lock.json
      - name: Install web dependencies
        working-directory: web
        run: npm ci
      - name: Build embedded UI
        working-directory: web
        run: npm run build
      - name: Build server with the real UI
        run: |
          rm -rf cmd/visitflow/webdist
          mkdir -p cmd/visitflow/webdist
          cp -r web/dist/. cmd/visitflow/webdist/
          go build -o visitflow ./cmd/visitflow
      - name: Start VisitFlow
        env:
          POSTGRES_DSN: postgres://visitflow:visitflow@127.0.0.1:5432/visitflow?sslmode=disable
          BOOTSTRAP_ADMIN: admin
          BOOTSTRAP_ADMIN_PASSWORD: e2e-bootstrap-password
        run: |
          # Redirect the log so the server is not killed by SIGPIPE when this
          # step's shell exits and the pipe closes.
          ENCRYPTION_KEY="$(openssl rand -base64 32)" nohup ./visitflow > visitflow.log 2>&1 &
          for attempt in $(seq 1 30); do
            if curl -fsS http://127.0.0.1:8080/readyz > /dev/null; then exit 0; fi
            sleep 2
          done
          echo "VisitFlow did not become ready" >&2
          cat visitflow.log >&2 || true
          exit 1
      - name: Install Playwright browser
        working-directory: web
        run: npx playwright install --with-deps chromium
      - name: Browser end-to-end tests
        working-directory: web
        run: npm run test:e2e
      - uses: actions/upload-artifact@v4
        if: failure()
        with:
          name: playwright-report
          path: web/playwright-report
          retention-days: 7
import { defineConfig, devices } from "@playwright/test";

// The end-to-end suite drives a real VisitFlow instance: the lobby flows depend
// on camera permissions, keyboard-wedge scanners and server-verified QR codes,
// none of which a component test can stand in for.
export default defineConfig({
  testDir: "./e2e",
  timeout: 60_000,
  expect: { timeout: 10_000 },
  fullyParallel: false,
  workers: 1,
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? [["list"], ["html", { open: "never" }]] : "list",
  use: {
    baseURL: process.env.VISITFLOW_BASE_URL ?? "http://127.0.0.1:8080",
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
    locale: "ko-KR",
    timezoneId: "Asia/Seoul",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
});

